import React, { useRef, useEffect, useState, useCallback } from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Alert from '@mui/material/Alert';
import Button from '@mui/material/Button';
import IconButton from '@mui/material/IconButton';
import CircularProgress from '@mui/material/CircularProgress';
import TextField from '@mui/material/TextField';
import Fade from '@mui/material/Fade';
import { alpha } from '@mui/material/styles';
import Cameraswitch from '@mui/icons-material/Cameraswitch';
import CloudUpload from '@mui/icons-material/CloudUpload';

const MODEL_URL = 'https://cdn.jsdelivr.net/gh/justadudewhohacks/face-api.js@0.22.2/weights/';
const DETECTION_FRAME_SKIP = 8;

export default function Camera() {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const displaySizeRef = useRef(null);
    const rafRef = useRef(null);
    const cancelledRef = useRef(false);
    const frameCountRef = useRef(0);
    const [error, setError] = useState(null);
    const [status, setStatus] = useState('Loading face detection models...');
    const [facingMode, setFacingMode] = useState('user');
    const [capturedImage, setCapturedImage] = useState(null);
    const [uploadStatus, setUploadStatus] = useState(null);
    const [targetUserId, setTargetUserId] = useState('');

    const stopStream = useCallback(() => {
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        if (videoRef.current?.srcObject) {
            videoRef.current.srcObject.getTracks().forEach((t) => t.stop());
            videoRef.current.srcObject = null;
        }
    }, []);

    const startCamera = useCallback(async (mode) => {
        const cancelled = cancelledRef.current;
        try {
            await Promise.all([
                faceapi.nets.ssdMobilenetv1.loadFromUri(MODEL_URL),
            ]);
            if (cancelledRef.current) return;
            setStatus('Starting camera...');

            if (!navigator.mediaDevices?.getUserMedia) {
                throw new Error('Camera access requires HTTPS. Access this page via HTTPS or localhost.');
            }
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: mode },
            });
            if (cancelledRef.current) return;
            const video = videoRef.current;
            if (!video) return;
            video.srcObject = stream;

            await new Promise((resolve) => {
                video.addEventListener('loadedmetadata', resolve, { once: true });
            });

            if (cancelledRef.current) return;
            try {
                await video.play();
            } catch (playErr) {
                if (!cancelledRef.current) setError(playErr.message);
                return;
            }

            const { videoWidth, videoHeight } = video;
            const canvas = canvasRef.current;
            const renderedWidth = video.offsetWidth || videoWidth;
            const renderedHeight = video.offsetHeight || videoHeight;
            const displaySize = { width: renderedWidth, height: renderedHeight };
            displaySizeRef.current = displaySize;

            faceapi.matchDimensions(canvas, displaySize);

            setStatus('Detecting faces...');
            detectLoop();
        } catch (err) {
            if (!cancelledRef.current) setError(err.message);
        }
    }, []);

    useEffect(() => {
        cancelledRef.current = false;
        stopStream();
        startCamera(facingMode);

        return () => {
            cancelledRef.current = true;
            stopStream();
        };
    }, [facingMode, startCamera, stopStream]);

    function detectLoop() {
        if (cancelledRef.current) return;
        const video = videoRef.current;
        const canvas = canvasRef.current;
        if (!video || !canvas || video.readyState < 2) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        frameCountRef.current += 1;
        if (frameCountRef.current % DETECTION_FRAME_SKIP !== 0) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        faceapi
            .detectAllFaces(video, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.5 }))
            .then((detections) => {
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                const displaySize = displaySizeRef.current;
                const resized = faceapi.resizeResults(detections, displaySize);

                if (facingMode === 'user') {
                    ctx.save();
                    ctx.translate(canvas.width, 0);
                    ctx.scale(-1, 1);
                }

                resized.forEach((d) => {
                    const box = d.box;
                    ctx.shadowColor = '#00ff88';
                    ctx.shadowBlur = 16;
                    ctx.strokeStyle = '#00ff88';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.roundRect(box.x, box.y, box.width, box.height, 8);
                    ctx.stroke();
                    ctx.shadowBlur = 0;
                });

                if (facingMode === 'user') {
                    ctx.restore();
                }

                rafRef.current = requestAnimationFrame(detectLoop);
            })
            .catch((err) => {
                if (!cancelledRef.current) setError(err.message);
            });
    }

    function capturePhoto() {
        const video = videoRef.current;
        if (!video || !video.videoWidth) return;
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = video.videoWidth;
        tempCanvas.height = video.videoHeight;
        tempCanvas.getContext('2d').drawImage(video, 0, 0);
        setCapturedImage(tempCanvas.toDataURL('image/jpeg', 0.8));
        setUploadStatus(null);
    }

    async function uploadPhoto() {
        if (!capturedImage || !targetUserId.trim()) return;
        setUploadStatus('Uploading...');
        try {
            const base64 = capturedImage.split(',')[1];
            const res = await fetch(`/api/user/${encodeURIComponent(targetUserId.trim())}/face`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ image: base64 }),
            });
            if (!res.ok) {
                const errText = await res.text();
                throw new Error(errText || `Server returned ${res.status}`);
            }
            const data = await res.json();
            setUploadStatus(`Uploaded! ${data.length} face(s) registered.`);
            setCapturedImage(null);
        } catch (err) {
            setUploadStatus(`Upload failed: ${err.message}`);
        }
    }

    function toggleCamera() {
        setFacingMode((prev) => (prev === 'user' ? 'environment' : 'user'));
    }

    return (
        <Box sx={{
            p: { xs: 1.5, sm: 3 },
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 2.5,
            bgcolor: '#0b0b12',
            minHeight: '100vh',
        }}>
            <Typography variant="h5" sx={{
                fontWeight: 700,
                color: '#fff',
                letterSpacing: '-0.3px',
            }}>
                Facial Recognition
            </Typography>

            {error && (
                <Alert severity="error" sx={{ width: '100%', maxWidth: 480 }}>
                    {error}
                </Alert>
            )}

            <Box sx={{
                position: 'relative',
                width: '100%',
                maxWidth: 480,
                mx: 'auto',
                borderRadius: 3,
                overflow: 'hidden',
                border: '1px solid',
                borderColor: alpha('#fff', 0.08),
                boxShadow: '0 8px 40px rgba(0,0,0,0.5)',
            }}>
                <Box
                    component="video"
                    ref={videoRef}
                    autoPlay
                    muted
                    playsInline
                    sx={{
                        display: 'block',
                        width: '100%',
                        height: 'auto',
                        transform: facingMode === 'user' ? 'scaleX(-1)' : 'none',
                    }}
                />
                <Box
                    component="canvas"
                    ref={canvasRef}
                    sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                    }}
                />

                {!error && (
                    <Box sx={{
                        position: 'absolute',
                        top: 12,
                        left: 12,
                        display: 'flex',
                        alignItems: 'center',
                        gap: 0.75,
                        px: 1.25,
                        py: 0.5,
                        borderRadius: 20,
                        backdropFilter: 'blur(10px)',
                        WebkitBackdropFilter: 'blur(10px)',
                        backgroundColor: alpha('#000', 0.5),
                    }}>
                        {status === 'Loading face detection models...' && (
                            <CircularProgress size={12} sx={{ color: '#fff' }} />
                        )}
                        <Typography sx={{
                            color: '#fff',
                            fontSize: 12,
                            fontWeight: 500,
                            lineHeight: 1.2,
                            letterSpacing: '0.2px',
                        }}>
                            {status}
                        </Typography>
                    </Box>
                )}

                <IconButton
                    onClick={toggleCamera}
                    sx={{
                        position: 'absolute',
                        top: 10,
                        right: 10,
                        backdropFilter: 'blur(10px)',
                        WebkitBackdropFilter: 'blur(10px)',
                        backgroundColor: alpha('#000', 0.4),
                        color: '#fff',
                        '&:hover': { backgroundColor: alpha('#000', 0.6) },
                        transition: 'all 0.2s',
                    }}
                >
                    <Cameraswitch />
                </IconButton>
            </Box>

            <IconButton
                onClick={capturePhoto}
                sx={{
                    width: 76,
                    height: 76,
                    border: '4px solid',
                    borderColor: alpha('#fff', 0.8),
                    backgroundColor: alpha('#fff', 0.08),
                    backdropFilter: 'blur(6px)',
                    WebkitBackdropFilter: 'blur(6px)',
                    '&:hover': { backgroundColor: alpha('#fff', 0.18), transform: 'scale(1.05)' },
                    transition: 'all 0.2s',
                }}
            >
                <Box sx={{
                    width: 58,
                    height: 58,
                    borderRadius: '50%',
                    bgcolor: '#fff',
                    boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.15)',
                }} />
            </IconButton>

            <Fade in={!!capturedImage} timeout={300}>
                <Box sx={{
                    width: '100%',
                    maxWidth: 480,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: 1.5,
                    p: 1.5,
                    borderRadius: 3,
                    border: '1px solid',
                    borderColor: alpha('#fff', 0.06),
                    bgcolor: alpha('#fff', 0.03),
                }}>
                    <Box
                        component="img"
                        src={capturedImage}
                        alt="Captured"
                        sx={{
                            width: '100%',
                            maxWidth: 320,
                            height: 'auto',
                            borderRadius: 2,
                            boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
                        }}
                    />
                    <Button
                        variant="contained"
                        size="large"
                        onClick={uploadPhoto}
                        disabled={!targetUserId.trim()}
                        startIcon={<CloudUpload />}
                        sx={{
                            borderRadius: 3,
                            px: 3,
                            py: 1,
                            fontWeight: 600,
                            textTransform: 'none',
                            fontSize: 15,
                        }}
                    >
                        Send to Server
                    </Button>
                </Box>
            </Fade>

            <TextField
                label="User ID"
                size="small"
                value={targetUserId}
                onChange={(e) => setTargetUserId(e.target.value)}
                sx={{
                    width: '100%',
                    maxWidth: 480,
                    '& .MuiOutlinedInput-root': {
                        borderRadius: 3,
                        bgcolor: alpha('#fff', 0.04),
                        '& fieldset': { borderColor: alpha('#fff', 0.12) },
                        '&:hover fieldset': { borderColor: alpha('#fff', 0.25) },
                        '&.Mui-focused fieldset': { borderColor: alpha('#fff', 0.5) },
                    },
                    '& .MuiInputLabel-root': { color: alpha('#fff', 0.5) },
                    '& .MuiInputBase-input': { color: '#fff' },
                }}
            />

            {uploadStatus && (
                <Fade in timeout={250}>
                    <Alert
                        severity={uploadStatus.startsWith('Uploaded') ? 'success' : 'error'}
                        sx={{
                            width: '100%',
                            maxWidth: 480,
                            borderRadius: 2,
                        }}
                    >
                        {uploadStatus}
                    </Alert>
                </Fade>
            )}
        </Box>
    );
}
